from sklearn.cluster import KMeans


def kmeans_sizes(points):
    model = KMeans(n_clusters=2, n_init=10, random_state=0)
    labels = model.fit_predict(points)
    sizes = [int((labels == k).sum()) for k in range(2)]
    return sorted(sizes)
